# users/api/views.py
#
# Database: MySQL  ← all raw SQL here is MySQL-compatible.
#
# Key MySQL rules followed throughout this file:
#   - Parameterised values always use %s  (MySQLdb/mysqlclient style)
#   - LAST_INSERT_ID() used after every INSERT to get the new PK
#     (safe and atomic — it returns the ID generated by *this* connection,
#      so concurrent inserts from other connections never interfere)
#   - No RETURNING clause (PostgreSQL-only — not supported by MySQL)
#   - TINYINT(1) used for booleans  (MySQL has no native BOOLEAN type;
#     Django stores BooleanField as tinyint(1), so we pass 0/1)
#   - String literals use single quotes in SQL, %s for parameters
#   - LIMIT without OFFSET written as LIMIT n  (MySQL syntax)
#
# Single RegisterView handles ALL roles: CUSTOMER, RIDER, RESTAURANT.
# Rider registration also inserts into:
#   - addresses_address                    (the rider's home address)
#   - riders_rider                         (core rider profile)
#   - riders_rider_additional_information  (NID, wallet, emergency contact)
#
# insert_address() is a standalone helper so any other view can reuse it.

