from rest_framework_simplejwt.views import TokenObtainPairView
from django.db import connection, IntegrityError, transaction

from ..models import User
from .serializers import UserRegistrationSerializer, MyTokenObtainPairSerializer
from riders.api.services import validate_rider_fields, insert_rider
from customers.api.services import insert_customer
from resturants.api.services import insert_restaurant


# ─────────────────────────────────────────────────────────────────────────────
# REGISTRATION — one view for every role
# ─────────────────────────────────────────────────────────────────────────────

class RegisterView(APIView):
    """
    POST /api/auth/register/

    Handles sign-up for CUSTOMER, RIDER, and RESTAURANT roles.
    The 'role' field in the request body decides what extra tables get populated.

    ── Common fields (all roles) ──────────────────────────────────────────────
    {
        "first_name":   "John",
        "last_name":    "Doe",
        "email":        "john@example.com",
        "phone_number": "01712345678",
        "password":     "secret123",
        "password2":    "secret123",
        "role":         "RIDER"          # CUSTOMER | RIDER | RESTAURANT
    }

    ── Extra fields for RIDER  (send as multipart/form-data, NOT JSON) ────────
    {
        "vehicle":                  "BIKE",          # BIKE | CYCLE | SCOOTER
        "license_plate":            "DHA-1234",
        "street_address":           "Road 4, Block B",
        "city":                     "Dhaka",
        "latitude":                 23.780,          # optional
        "longitude":                90.420,          # optional
        "nid_number":               "1234567890",
        "gender":                   "Male",
        "wallet_balance":           0.00,            # optional, defaults to 0
        "emergency_contact_name":   "Jane Doe",
        "emergency_contact_number": "01798765432",
        // nid_front, nid_back → image files in multipart body
    }

    ── Extra fields for RESTAURANT ────────────────────────────────────────────
    {
        "restaurant_name":     "Kutumbari Restora",
        "restaurant_category": "RESTAURANT"          # optional
    }
    """
    permission_classes = [AllowAny]

    def post(self, request):
        print(request.data)
        # ── Step 1: validate base user fields via existing serializer ───────
        serializer = UserRegistrationSerializer(data=request.data)
        if not serializer.is_valid():
            return Response(serializer.errors, status=status.HTTP_400_BAD_REQUEST)

        # ── Step 2: extract validated common fields ──────────────────────────
        email        = serializer.validated_data['email']
        password     = make_password(serializer.validated_data['password'])
        phone_number = serializer.validated_data.get('phone_number', '')
        role         = serializer.validated_data.get('role', 'CUSTOMER')
        first_name   = serializer.validated_data.get('first_name', '')
        last_name    = serializer.validated_data.get('last_name', '')

        # MySQL stores BooleanField as TINYINT(1) — pass integers, not True/False
        is_superuser = 0
        is_staff     = 0
        is_active    = 1
        date_joined  = datetime.now()  # MySQL DATETIME — Python datetime works fine

        # ── Step 3: role-specific validation BEFORE touching the DB ─────────
        if role == 'RIDER':
            error_msg = validate_rider_fields(request.data, request.FILES)
            if error_msg:
                return Response({"error": error_msg}, status=status.HTTP_400_BAD_REQUEST)

        elif role == 'RESTAURANT':
            if not request.data.get('restaurant_name', '').strip():
                return Response(
                    {"error": "restaurant_name is required for Restaurant registration."},
                    status=status.HTTP_400_BAD_REQUEST
                )

        # ── Step 4: all DB inserts in a single atomic transaction ────────────
        # transaction.atomic() on MySQL uses InnoDB savepoints.
        # Any exception inside rolls back every INSERT in this block.
        try:
            with transaction.atomic():
                with connection.cursor() as cursor:
                    # 4a ── Insert the base users_user row ───────────────────
                    cursor.execute(
                        """
                        INSERT INTO users_user
                            (password, is_superuser, email, is_staff, is_active,
                             date_joined, role, phone_number, image_url,
                             first_name, last_name)
                        VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                        """,
                        [
                            password, is_superuser, email, is_staff, is_active,
                            date_joined, role, phone_number, '',
                            first_name, last_name,
                        ]
                    )

                    # Use LAST_INSERT_ID() — atomic and connection-scoped in MySQL.
                    # Never use SELECT WHERE email here; another thread could
                    # INSERT the same email between our INSERT and SELECT.
                    cursor.execute("SELECT LAST_INSERT_ID()")
                    row = cursor.fetchone()
                    if not row or not row[0]:
                        raise Exception("MySQL did not return a valid user ID after INSERT.")
                    new_user_id = row[0]

                    # 4b ── Role-specific child table inserts ─────────────────
                    if role == 'CUSTOMER':
                        insert_customer(cursor, new_user_id)

                    elif role == 'RIDER':
                        # Cloudinary uploads happen inside this method.
                        # If an upload fails it raises, which triggers rollback.
                        insert_rider(cursor, new_user_id, request)

                    elif role == 'RESTAURANT':
                        insert_restaurant(
                            cursor, new_user_id, phone_number, request.data
                        )

            return Response(
                {"message": f"{role.capitalize()} registered successfully"},
                status=status.HTTP_201_CREATED
            )

        except IntegrityError:
            # MySQL raises IntegrityError for duplicate UNIQUE keys
            # (email or phone_number in this case)
            return Response(
                {"error": "A user with this email or phone number already exists."},
                status=status.HTTP_400_BAD_REQUEST
            )
        except Exception as e:
            return Response({"error": str(e)}, status=status.HTTP_500_INTERNAL_SERVER_ERROR)
    

    


